{"type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01SRG6rrdLaARX2DS2auMy9X","type":"tool_result","content":"{\"result\":\"{\\\"success\\\": true, \\\"data\\\": {\\\"stdout\\\": \\\"#!/usr/bin/env python3\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\nMVP-A Oracle Information Gain Monte Carlo Simulation\\\\n\\\\nCompares per-test verifier vs trajectory-level verifier for best-of-N\\\\npatch selection under i.i.d. and block-correlated noise models.\\\\n\\\\nSetup: N=16 candidate patches, 1 correct (all tests pass), N-1 wrong\\\\n(random subset of tests fail). T tests per instance sampled from\\\\nlognormal(2.5, 0.8) truncated to [2, 100].\\\\n\\\\nPer-test verifier: predicts each test pass/fail at accuracy p, ranks\\\\npatches by predicted pass count, selects highest.\\\\nTrajectory-level verifier: binary resolved/unresolved prediction at\\\\naccuracy p per patch, selects randomly from predicted-resolved set.\\\\n\\\\nBoth verifiers operate at the same per-prediction accuracy p. The\\\\nper-test advantage comes from having T observations per patch (ranking\\\\nby continuous score) vs 1 observation (binary classification).\\\\n\\\\nOutput: mvp_a_results.json (data), mvp_a_curves.pdf (visualization)\\\\n\\\\\\\"\\\\\\\"\\\\\\\"\\\\n\\\\nimport numpy as np\\\\nimport json\\\\nimport argparse\\\\nimport time\\\\nimport os\\\\n\\\\nimport matplotlib\\\\nmatplotlib.use('Agg')\\\\nimport matplotlib.pyplot as plt\\\\n\\\\n\\\\ndef sample_test_counts(rng, n):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Sample test counts from lognormal(2.5, 0.8) truncated to [2, 100].\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    raw = rng.lognormal(mean=2.5, sigma=0.8, size=n)\\\\n    return np.clip(raw, 2, 100).astype(int)\\\\n\\\\n\\\\ndef build_ground_truth(rng, n_trials, N, T_values, T_max):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    Build ground truth pass/fail for all trials.\\\\n    Patch 0 is correct (all pass). Others have random failures.\\\\n    Returns (n_trials, N, T_max) bool, True=pass.\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    gt = np.ones((n_trials, N, T_max), dtype=bool)\\\\n    for trial in range(n_trials):\\\\n        T = T_values[trial]\\\\n        for patch in range(1, N):\\\\n            fail_prob = rng.uniform(0.1, 0.8)\\\\n            fails = rng.random(T) < fail_prob\\\\n            if not fails.any():\\\\n                fails[rng.integers(T)] = True\\\\n            gt[trial, patch, :T] = ~fails\\\\n    return gt\\\\n\\\\n\\\\ndef build_block_structure(rng, T_values, T_max):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    Assign tests to blocks of size 2-8 for block-correlated noise.\\\\n    Returns block_ids (n_trials, T_max) and n_blocks (n_trials,).\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"\\\\n    n_trials = len(T_values)\\\\n    block_ids = np.zeros((n_trials, T_max), dtype=np.int32)\\\\n    n_blocks_arr = np.zeros(n_trials, dtype=np.int32)\\\\n\\\\n    for trial in range(n_trials):\\\\n        T = T_values[trial]\\\\n        idx, bid = 0, 0\\\\n        while idx < T:\\\\n            remaining = T - idx\\\\n            if remaining <= 8:\\\\n                block_ids[trial, idx:T] = bid\\\\n                bid += 1\\\\n                break\\\\n            bs = min(int(rng.integers(2, 9)), remaining)\\\\n            block_ids[trial, idx:idx + bs] = bid\\\\n            bid += 1\\\\n            idx += bs\\\\n        n_blocks_arr[trial] = bid\\\\n\\\\n    return block_ids, n_blocks_arr\\\\n\\\\n\\\\ndef select_best_patch(scores, rng):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Select patch with highest score per trial, random tiebreak.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    tiebreak = rng.random(scores.shape) * 1e-6\\\\n    return (scores.astype(np.float64) + tiebreak).argmax(axis=1)\\\\n\\\\n\\\\ndef select_from_resolved(preds, rng):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Select randomly from predicted-resolved patches; if none, random from all.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    tiebreak = rng.random(preds.shape)\\\\n    any_resolved = preds.any(axis=1, keepdims=True)\\\\n    masked = np.where(preds, tiebreak, -1.0)\\\\n    effective = np.where(any_resolved, masked, tiebreak)\\\\n    return effective.argmax(axis=1)\\\\n\\\\n\\\\ndef run_simulation(N=16, n_trials=10000, accuracy_range=None, seed=42):\\\\n    \\\\\\\"\\\\\\\"\\\\\\\"Run full Monte Carlo simulation.\\\\\\\"\\\\\\\"\\\\\\\"\\\\n    if accuracy_range is None:\\\\n        accuracy_range = np.arange(0.55, 1.00, 0.01)\\\\n\\\\n    rng = np.random.default_rng(seed)\\\\n    n_acc = len(accuracy_range)\\\\n\\\\n    print(\\\\\\\"Preparing trials...\\\\\\\")\\\\n    T_values = sample_test_counts(rng, n_trials)\\\\n    T_max = int(T_values.max())\\\\n    print(f\\\\\\\"  T: median={np.median(T_values):.0f}, mean={T_values.mean():.1f}, \\\\\\\"\\\\n          f\\\\\\\"range=[{T_values.min()}, {T_values.max()}]\\\\\\\")\\\\n\\\\n    gt = build_ground_truth(rng, n_trials, N, T_values, T_max)\\\\n    test_mask = (np.arange(T_max)[None, :] < T_values[:, None])[:, None, :]\\\\n\\\\n    block_ids, n_blocks = build_block_structu\\\\n\\\\n... [截断: 输出过长，省略 4995 字符] ...\\\\n\\\\ne(y=0.05, color='green', ls=':', lw=1.5, label='5% threshold')\\\\n    ax2.axhline(y=0, color='gray', ls='-', lw=0.5)\\\\n    ax2.axvspan(0.70, 0.85, alpha=0.08, color='green')\\\\n\\\\n    bm = advantages['target_range_block']['mean']\\\\n    im = advantages['target_range_iid']['mean']\\\\n    ax2.annotate(f'Block mean: {bm:.1%}', xy=(0.775, bm),\\\\n                fontsize=10, ha='center', va='bottom',\\\\n                bbox=dict(boxstyle='round,pad=0.3', fc='mistyrose', alpha=0.9))\\\\n    ax2.annotate(f'I.I.D. mean: {im:.1%}', xy=(0.775, im),\\\\n                fontsize=10, ha='center', va='bottom',\\\\n                bbox=dict(boxstyle='round,pad=0.3', fc='lightcyan', alpha=0.9))\\\\n\\\\n    ax2.set_xlabel('Per-test Accuracy', fontsize=12)\\\\n    ax2.set_ylabel('Per-test Advantage (absolute)', fontsize=12)\\\\n    ax2.set_title('Advantage of Per-test over Trajectory', fontsize=13)\\\\n    ax2.legend(fontsize=10)\\\\n    ax2.grid(True, alpha=0.3)\\\\n    ax2.set_xlim(min(acc), max(acc))\\\\n\\\\n    plt.tight_layout()\\\\n    plt.savefig(output_path, dpi=150, bbox_inches='tight')\\\\n    plt.close()\\\\n    print(f\\\\\\\"Saved {output_path}\\\\\\\")\\\\n\\\\n\\\\ndef main():\\\\n    parser = argparse.ArgumentParser(\\\\n        description='MVP-A: per-test vs trajectory-level verifier Monte Carlo simulation')\\\\n    parser.add_argument('--N', type=int, default=16,\\\\n                        help='Number of candidate patches (default: 16)')\\\\n    parser.add_argument('--n-trials', type=int, default=10000,\\\\n                        help='Monte Carlo trials per accuracy level (default: 10000)')\\\\n    parser.add_argument('--acc-min', type=float, default=0.55)\\\\n    parser.add_argument('--acc-max', type=float, default=0.99)\\\\n    parser.add_argument('--acc-step', type=float, default=0.01)\\\\n    parser.add_argument('--seed', type=int, default=42)\\\\n    parser.add_argument('--output-json', default='mvp_a_results.json')\\\\n    parser.add_argument('--output-pdf', default='mvp_a_curves.pdf')\\\\n    args = parser.parse_args()\\\\n\\\\n    acc_range = np.round(np.arange(args.acc_min, args.acc_max + 1e-9, args.acc_step), 2)\\\\n\\\\n    print(\\\\\\\"MVP-A Oracle Information Gain Simulation\\\\\\\")\\\\n    print(f\\\\\\\"  N={args.N}, trials={args.n_trials}, \\\\\\\"\\\\n          f\\\\\\\"acc={args.acc_min:.2f}-{args.acc_max:.2f}, seed={args.seed}\\\\\\\")\\\\n    print()\\\\n\\\\n    results = run_simulation(args.N, args.n_trials, acc_range, args.seed)\\\\n    advantages = compute_advantages(results)\\\\n\\\\n    # --- Pass criterion ---\\\\n    bm = advantages['target_range_block']['mean']\\\\n    im = advantages['target_range_iid']['mean']\\\\n    passed = bm >= 0.05\\\\n\\\\n    print()\\\\n    print(\\\\\\\"=\\\\\\\" * 60)\\\\n    print(\\\\\\\"MVP-A PASS CRITERION\\\\\\\")\\\\n    print(\\\\\\\"=\\\\\\\" * 60)\\\\n    print(f\\\\\\\"Block-correlated, 70-85% accuracy 